-- INSERT INTO TAGS (ID, COUNT, EXCERPTPOSTID) VALUES (NULL, 6000, NULL); -- This would make Q1 output 0 and Q2 output 1, but it's not allowed.
-- For a valid example under constraints, both queries output the same, as shown below:
